(3327141, 459800, 45919, '<td valign="top">I find the two lines across the image too off putting.</td>', 'I find the two lines across the image too off putting.', '2007-02-04 19:17:12.000000', NULL, 1),
(3327144, 460478, 45919, '<td valign="top">Excellent use of monochrome and love the rule of 3s use, nice.</td>', 'Excellent use of monochrome and love the rule of 3s use, nice.', '2007-02-04 19:17:41.000000', NULL, 1),
