(3327159, 460474, 45919, '<td valign="top">Interesting image but to me it appears slightly out of focus.</td>', 'Interesting image but to me it appears slightly out of focus.', '2007-02-04 19:21:20.000000', NULL, 1),
(3327163, 460064, 45919, '<td valign="top">Nice use of lighting.</td>', 'Nice use of lighting.', '2007-02-04 19:22:06.000000', NULL, 1),
